// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.evaluation.util.QueryEvaluationUtility;
import org.eclipse.rdf4j.query.algebra.helpers.TupleExprs;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Test;

/**
 * {@link NativeTupleFacts} (M-A1c): the tuple-level fact authority computed from pinned snapshots. Each test pins one
 * fact on representative parsed algebra — these facts gate island reuse selection, keyed memoization, and movement, so
 * a wrong answer here silently disables or (worse) wrongly enables an optimization.
 */
public class LmdbNativeTupleFactsTest {

	private static final String EX = "http://example.com/";

	private NativeTupleFacts factsOf(String where) {
		String query = "SELECT * WHERE { " + where + " }";
		TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		TupleExpr arg = parsed instanceof QueryRoot ? ((QueryRoot) parsed).getArg() : parsed;
		// the facts contract expects a pinned snapshot, exactly as GenericSubplanDescriptor.create produces one
		return NativeTupleFacts.of(QueryEvaluationUtility.pinFunctions((TupleExpr) arg.clone()));
	}

	@Test
	public void plainJoinIsRepeatableDiscardableAndNotMappingParameterized() {
		NativeTupleFacts facts = factsOf("?s <" + EX + "p> ?o . ?s <" + EX + "q> ?n");
		assertThat(facts.repeatable()).isTrue();
		assertThat(facts.shareableAcrossEvaluations()).isTrue();
		assertThat(facts.mappingParameterized()).isFalse();
		assertThat(facts.discardable()).isTrue();
		assertThat(facts.observedNames()).contains("s", "o", "n");
	}

	@Test
	public void volatileBindIsNotRepeatable() {
		NativeTupleFacts facts = factsOf("?s <" + EX + "p> ?o . BIND(UUID() AS ?u)");
		assertThat(facts.repeatable()).isFalse();
		assertThat(facts.shareableAcrossEvaluations()).isFalse();
		assertThat(facts.observedNames()).contains("u");
	}

	@Test
	public void nowIsRepeatableButNotShareable() {
		NativeTupleFacts facts = factsOf("?s <" + EX
				+ "p> ?o . FILTER(NOW() > \"2000-01-01T00:00:00Z\"^^<http://www.w3.org/2001/XMLSchema#dateTime>)");
		assertThat(facts.repeatable()).isTrue();
		assertThat(facts.shareableAcrossEvaluations()).isFalse();
	}

	@Test
	public void propertyPathIsMappingParameterized() {
		NativeTupleFacts facts = factsOf("?s <" + EX + "p>+ ?o");
		assertThat(facts.mappingParameterized()).isTrue();
	}

	@Test
	public void serviceIsMappingParameterizedAndNotDiscardable() {
		NativeTupleFacts facts = factsOf("SERVICE <" + EX + "endpoint> { ?s ?p ?o }");
		assertThat(facts.mappingParameterized()).isTrue();
		assertThat(facts.mayRaiseQueryFatalError()).isTrue();
		assertThat(facts.discardable()).isFalse();
	}

	@Test
	public void silentServiceIsDiscardable() {
		NativeTupleFacts facts = factsOf("SERVICE SILENT <" + EX + "endpoint> { ?s ?p ?o }");
		assertThat(facts.discardable()).isTrue();
	}

	@Test
	public void subqueryProducesOnlyProjectedNames() {
		NativeTupleFacts facts = factsOf("{ SELECT ?s WHERE { ?s <" + EX + "p> ?hidden } }");
		assertThat(facts.producedNames()).containsExactly("s");
		assertThat(facts.observedNames()).contains("s", "hidden");
	}

	@Test
	public void extensionTargetIsObserved() {
		NativeTupleFacts facts = factsOf("?s <" + EX + "p> ?o . BIND(STR(?o) AS ?str)");
		assertThat(facts.observedNames()).contains("str", "o");
		assertThat(facts.producedNames()).contains("str");
	}

	@Test
	public void minusSubtreeStaysRepeatable() {
		NativeTupleFacts facts = factsOf("?s <" + EX + "p> ?o MINUS { ?s <" + EX + "q> ?n }");
		assertThat(facts.repeatable()).isTrue();
		assertThat(facts.mappingParameterized()).isFalse();
	}

	@Test
	public void unionArmScopeChangeIsVisibleOnTheArm() {
		String query = "SELECT * WHERE { { ?s <" + EX + "p> ?o } UNION { ?s <" + EX + "q> ?n } }";
		TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		boolean[] visited = { false };
		parsed.visit(new org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(org.eclipse.rdf4j.query.algebra.Union node) {
				visited[0] = true;
				NativeTupleFacts arm = NativeTupleFacts.of(node.getLeftArg());
				assertThat(arm.scopeChange()).isEqualTo(
						TupleExprs.isVariableScopeChange(node.getLeftArg()));
			}
		});
		assertThat(visited[0]).isTrue();
	}
}
